        impl Rand32 { # [doc = " The default value for `increment`."] # [doc = " This is basically arbitrary, it comes from the"] # [doc = " PCG reference C implementation:"] # [doc = " https://github.com/imneme/pcg-c/blob/master/include/pcg_variants.h#L284"] pub const DEFAULT_INC : u64 = 1442695040888963407 ; # [doc = " This is the number that you have to Really Get Right."] # [doc = ""] # [doc = " The value used here is from the PCG C implementation:"] # [doc = " https://github.com/imneme/pcg-c/blob/master/include/pcg_variants.h#L278"] pub (crate) const MULTIPLIER : u64 = 6364136223846793005 ; # [doc = " Creates a new PRNG with the given seed and a default increment."] pub fn new (seed : u64) -> Self { Self :: new_inc (seed , Self :: DEFAULT_INC) } # [doc = " Creates a new PRNG.  The two inputs, `seed` and `increment`,"] # [doc = " determine what you get; `increment` basically selects which"] # [doc = " sequence of all those possible the PRNG will produce, and the"] # [doc = " `seed` selects where in that sequence you start."] # [doc = ""] # [doc = " Both are arbitrary; increment must be an odd number but this"] # [doc = " handles that for you"] pub fn new_inc (seed : u64 , increment : u64) -> Self { let mut rng = Self { state : 0 , inc : increment . wrapping_shl (1) | 1 , } ; let _ = rng . rand_u32 () ; rng . state = rng . state . wrapping_add (seed) ; let _ = rng . rand_u32 () ; rng } # [doc = " Returns the internal state of the PRNG.  This allows"] # [doc = " you to save a PRNG and create a new one that will resume"] # [doc = " from the same spot in the sequence."] pub fn state (& self) -> (u64 , u64) { (self . state , self . inc) } # [doc = " Creates a new PRNG from a saved state from `Rand32::state()`."] # [doc = " This is NOT quite the same as `new_inc()` because `new_inc()` does"] # [doc = " a little extra setup work to initialize the state."] pub fn from_state (state : (u64 , u64)) -> Self { let (state , inc) = state ; Self { state , inc } } # [doc = " Produces a random `u32` in the range `[0, u32::MAX]`."] pub fn rand_u32 (& mut self) -> u32 { let oldstate : u64 = self . state ; self . state = oldstate . wrapping_mul (Self :: MULTIPLIER) . wrapping_add (self . inc) ; let xorshifted : u32 = (((oldstate >> 18) ^ oldstate) >> 27) as u32 ; let rot : u32 = (oldstate >> 59) as u32 ; xorshifted . rotate_right (rot) } # [doc = " Produces a random `i32` in the range `[i32::MIN, i32::MAX]`."] pub fn rand_i32 (& mut self) -> i32 { self . rand_u32 () as i32 } # [doc = " Produces a random `f32` in the range `[0.0, 1.0)`."] pub fn rand_float (& mut self) -> f32 { const TOTAL_BITS : u32 = 32 ; const PRECISION : u32 = core :: f32 :: MANTISSA_DIGITS ; const MANTISSA_SCALE : f32 = 1.0 / ((1u32 << PRECISION) as f32) ; let mut u = self . rand_u32 () ; u >>= TOTAL_BITS - PRECISION ; u as f32 * MANTISSA_SCALE } # [doc = " Produces a random within the given bounds.  Like any `Range`,"] # [doc = " it includes the lower bound and excludes the upper one."] # [doc = ""] # [doc = " This should be faster than `Self::rand() % end + start`, but the"] # [doc = " real advantage is it's more convenient.  Requires that"] # [doc = " `range.end <= range.start`."] pub fn rand_range (& mut self , range : Range < u32 >) -> u32 { debug_assert ! (range . start < range . end) ; let range_starting_from_zero = 0 .. (range . end - range . start) ; let s : u32 = range_starting_from_zero . end ; let mut m : u64 = u64 :: from (self . rand_u32 ()) * u64 :: from (s) ; let mut leftover : u32 = (m & 0xFFFF_FFFF) as u32 ; if leftover < s { let threshold : u32 = s . wrapping_neg () % s ; while leftover < threshold { m = u64 :: from (self . rand_u32 ()) . wrapping_mul (u64 :: from (s)) ; leftover = (m & 0xFFFF_FFFF) as u32 ; } } (m >> 32) as u32 + range . start } }
